import { TestBed } from '@angular/core/testing';
import { of } from 'rxjs';
import { DownloadBlob } from '@shared/data/repository/provider/repository-provider.interface';
import { ListViewImageComponent } from './list-view-image.component';

describe('ListViewImageComponent', () => {
  function render(file: string | null) {
    const fixture = TestBed.createComponent(ListViewImageComponent);
    fixture.componentRef.setInput('file', file);
    fixture.componentRef.setInput('download', () =>
      of(new DownloadBlob(new Blob(['x'], { type: 'image/png' }), 'x.png')),
    );
    fixture.detectChanges();
    fixture.detectChanges();
    document.body.appendChild(fixture.nativeElement);
    return fixture;
  }

  it('renders the image round, like an avatar', () => {
    const fixture = render('plan.png');
    const img = fixture.nativeElement.querySelector('img.list-view-image') as HTMLImageElement;
    expect(img).not.toBeNull();
    expect(getComputedStyle(img).borderRadius).toBe('50%');
    fixture.nativeElement.remove();
  });

  it('renders nothing without a file', () => {
    const fixture = render(null);
    expect(fixture.nativeElement.querySelector('img')).toBeNull();
    fixture.nativeElement.remove();
  });
});
